script:
if doc.is_active:
    active = frappe.db.get_value(
        "Dealer Category Criteria Paper",
        {"is_active": 1, "name": ["!=", doc.name]},
        "name",
    )
    if active:
        frappe.throw(
            "Dealer Category Criteria Paper " + active + " is already active. Deactivate it before activating this document.",
            title="Another Document Is Active",
        )
